'use strict';
// Original Google Ads UI crops. No account identifiers or reconstructed pixels.
const REAL_SCREENS=[
{file:'overview.png',title:['Dashboard se shuru karo','Start at the dashboard'],path:'Campaigns → Overview',pins:[[26,46]],notes:[['New campaign setup ka darwaza hai. Pehle goal, budget aur measurement plan tayyar karo.','New campaign opens setup. Prepare your goal, budget and measurement plan first.']],task:['Apne business ka ek measurable result likho: qualified lead ya paid order.','Write one measurable business result: a qualified lead or paid order.']},
{file:'objectives-sales-leads.png',title:['Business ka objective choose karo','Choose a business objective'],path:'Create → Campaign → Objective',pins:[[18,62],[66,62]],notes:[['Sales: jab paid purchase ya revenue tumhara business result ho.','Sales: when a paid purchase or revenue is your business outcome.'],['Leads: jab enquiry ke baad qualification aur sale hoti ho. Leads objective apne aap quality guarantee nahi karta.','Leads: when enquiries need qualification and follow-up. The Leads objective does not guarantee lead quality.']],task:['AC repair ke liye qualified enquiry; shoe store ke liye paid order. Sirf click ko sale mat samjho.','For AC repair, use a qualified enquiry; for a shoe store, a paid order. A click is not a sale.']},
{file:'search-type.png',title:['Search campaign ko pehchano','Recognize a Search campaign'],path:'Objective → Conversion goals review → Campaign type',pins:[[20,47],[67,47]],notes:[['Search tile: Google Search par intent ke mutabiq text ads. Is course mein isi type ki practice hai.','Search tile: text ads on Google Search that respond to intent. This is the campaign type practised in this course.'],['Performance Max alag campaign type hai jo multiple channels use kar sakti hai. Ye sirf Search setup ka doosra naam nahi.','Performance Max is a separate campaign type that can use multiple channels. It is not another name for a Search campaign.']],task:['Search tile dhoondo. Agla decision conversion goal ka business result se match hona hai.','Find the Search tile. Check that the conversion goal matches your business outcome.']},
{file:'goals-navigation.png',title:['Measurement ka rasta','Find measurement settings'],path:'Goals → Conversions → Summary',pins:[[10,46],[65,8]],notes:[['Goals icon se conversion measurement ki navigation khulti hai. Billing ya campaign budget se ye alag section hai.','The Goals icon opens conversion measurement navigation. This is separate from billing or campaign budgets.'],['Summary entry point hai. Action ka source, primary/secondary status aur actual firing ko alag verify karo. Menu labels account ke mutabiq differ kar saktay hain.','Summary is an entry point. Verify each action’s source, primary/secondary status and actual firing separately. Menu labels may vary by account.']],task:['Tracking playground mein invalid form, success aur repeated event test karo.','Test an invalid form, a successful submission and a repeated event in the tracking playground.']},
{file:'campaign-controls.png',title:['Reporting controls par nazar','Find reporting controls'],path:'Campaigns → Campaigns → Table toolbar',pins:[[43,65],[66,65]],notes:[['Columns se apne business ke relevant metrics choose hotay hain. Clicks ke saath conversions, cost/conv. aur conversion value ko context mein dekho.','Columns selects relevant metrics. Read clicks alongside conversions, cost/conv. and conversion value in context.'],['Reports aur Download analysis ke liye hain. Date range, filters aur conversion delay ko samjhay baghair numbers compare mat karo.','Reports and Download support analysis. Check dates, filters and conversion delay before comparing numbers.']],task:['Weekly workbook mein spend, qualified leads aur actual customers ka comparison banao.','Compare spend, qualified leads and actual customers in the weekly workbook.']},
{file:'planner-home.jpg',date:'22 Oct 2026',width:730,practice:'studio',title:['Keyword Planner ke do rastay','Two Keyword Planner entry points'],path:'Tools → Planning → Keyword Planner',pins:[[24,67],[75,67]],notes:[['Discover new keywords: seed ideas se research shuru hoti hai. Ye crop sirf entry screen hai; live demand ya CPC ki report nahi.','Discover new keywords starts idea research. This crop shows only the entry screen, not live demand or CPC results.'],['Get search volume and forecasts: apni list ko estimates ke context mein dekho. Forecast actual customers ya profit ki guarantee nahi.','Get search volume and forecasts puts your list into an estimate context. Forecasts do not guarantee customers or profit.']],task:['AC repair Lahore ke 5 seed ideas studio mein likho; har idea ki business relevance explain karo.','Write five AC repair Lahore seeds in the studio and explain their business relevance.']},
{file:'planner-discover.jpg',date:'22 Oct 2026',width:772,practice:'studio',title:['Research inputs ko context do','Set the research context'],path:'Keyword Planner → Discover new keywords → Start with keywords',pins:[[28,36],[26,44],[18,71]],notes:[['Yahan apne product/service ke seed terms likhtay hain. Is capture mein koi search submit nahi hui aur results report capture nahi ki gayi.','Enter product/service seeds here. No search was submitted and no results report was captured.'],['Language aur location seed input ke neeche hain. Is screen ka Pakistan/English context example hai; apne actual market ka context verify karo.','Language and location sit below the seed input. Pakistan/English is the context shown here; verify the context for your actual market.'],['Optional site field unrelated ideas filter karne mein help karta hai. Website field aur target customer ki search language ko alag decisions samjho.','The optional site field helps filter unrelated ideas. Treat the website filter and customer search language as separate decisions.']],task:['Teen cheezain likho: service seed, target area aur relevant page. Estimates ko kaunse market/date context mein review karoge?','Write a service seed, target area and relevant page. In which market/date context will you review estimates?']},
{file:'conversion-diagnostics.jpg',date:'22 Oct 2026',width:815,practice:'clinic',title:['Diagnostics ka entry point','Find conversion Diagnostics'],path:'Goals → Conversions → Summary → Diagnostics',pins:[[16,17],[20,93]],notes:[['Diagnostics tab measurement setup ko inspect karne ka entry point hai. Is crop mein actual conversion-action diagnostics ya live firing ka proof nahi.','Diagnostics is an entry point for inspecting measurement setup. This crop does not show action-specific diagnostics or prove live firing.'],['Education card ki Learn more guidance aur actual test evidence alag hain. Tag Assistant, backend outcome aur Ads attribution separately verify karo.','The education card and actual test evidence are separate. Verify Tag Assistant behavior, backend outcomes and Ads attribution independently.']],task:['Tracking clinic mein paid order aur emitted conversion count/value compare karo. Sirf green indicator ko backend sale mat samjho.','Compare paid orders with emitted conversion counts/values in the clinic. A green indicator alone is not a backend sale.']},
{file:'date-range.jpg',date:'22 Oct 2026',width:495,practice:'optimize',title:['Pehle reporting period dekho','Check the reporting period first'],path:'Campaigns → Overview → Date range selector',pins:[[15,43],[70,10]],notes:[['Preset period report ki window choose karta hai. Last 7 days aur Last 30 days same evidence nahi; date selection budget ya bid change nahi.','A preset chooses the reporting window. Last 7 days and Last 30 days are different evidence; this is not a budget/bid change.'],['Start/end dates ko verify karo. Recent periods mein conversion delay aur incomplete outcomes ka context bhi chahiye. Is capture ke baad selection apply nahi ki gayi.','Verify start/end dates. Recent periods also need conversion-delay and outcome-maturity context. No new date selection was applied after capture.']],task:['Optimization lab ka conversion-delay case solve karo: kal ka CPA mature period ke CPA se seedha compare kyun nahi karna?','Solve the optimization conversion-delay case: why should yesterday’s CPA not be compared directly with a mature period?']}
,
{file:'bid-strategies.jpg',date:'22 Oct 2026',width:1100,practice:'lab',sources:['bidtargets','bid'],title:['Search bidding ke asli options','Original Search bidding choices'],path:'New Search setup → Bidding → Focus dropdown',pins:[[23,51],[23,41],[23,33]],notes:[['Target CPA aur Target ROAS is account ke current menu mein separate labels hain. Label dekh kar strategy ki target requirement aur measurement readiness review karo.','Target CPA and Target ROAS are separate labels in this account’s current menu. Review the target requirement and measurement readiness.'],['Maximize conversions count par focus karta hai; conversion value wala option value par. Galat goal/value tracking se strategy useful business outcome nahi samajh sakti.','Maximize conversions focuses on counts; the conversion-value option focuses on value. Incorrect goals/values undermine the business signal.'],['Recommended label har business ke liye proof nahi. Existing goals, reliable data, economics aur available strategy controls separately assess karo.','A Recommended label is not proof for every business. Assess goals, reliable data, economics and available controls separately.']],task:['AC repair mein raw forms ya qualified booking? Strategy choose karne se pehle apna biddable outcome aur evidence likho.','Raw forms or qualified bookings for AC repair? Define the biddable outcome and evidence before choosing a strategy.']},
{file:'target-cpa.jpg',date:'22 Oct 2026',width:842,practice:'calculators',sources:['bidtargets'],title:['Target CPA field samjho','Understand the Target CPA field'],path:'Search setup → Bidding → Target CPA',pins:[[25,32],[25,65]],notes:[['Target CPA selected honay par target amount ka field aata hai. Yeh average acquisition-cost target hai, har individual conversion ka hard price cap nahi.','Selecting Target CPA reveals a target-amount field. This is an average acquisition-cost target, not a hard cap for every conversion.'],['Currency aur business economics verify karo. Screenshot mein amount blank hai; koi live target set nahi kiya gaya.','Verify the currency and business economics. The amount is blank in this capture; no live target was set.']],task:['Break-even lead cost calculate karo; target ki reason aur mature qualified results ka review plan likho.','Calculate break-even lead cost; record a rationale for the target and a review plan using mature qualified results.']},
{file:'search-budget.jpg',date:'22 Oct 2026',width:1160,practice:'calculators',sources:['budget','budgettotal'],title:['Daily aur total budget alag hain','Daily and total budgets differ'],path:'Search setup → Budget → Select budget type',pins:[[22,60],[30,73],[22,85]],notes:[['Average daily budget har din ki fixed spend promise nahi. Most campaigns ke daily/monthly charging limits ko current budget guidance se verify karo.','An average daily budget is not a fixed daily-spend promise. Verify the current daily/monthly charging limits for the campaign.'],['PKR amount field blank hai. Currency, runway aur outcome economics dekh kar plan banao; recommendation ko affordable spend ki proof mat samjho.','The PKR amount field is blank. Plan using currency, runway and outcome economics; a recommendation does not establish affordability.'],['Campaign total budget duration ke liye alag type hai. Average-daily rules ko total budget par apply mat karo; type-switch restrictions aur dates pehle verify karo.','A campaign total budget covers a duration and is a different type. Do not apply average-daily rules to it; verify dates and switching restrictions first.']],task:['Daily aur total plan ke liye apna allowed total spend aur duration likho. App ka daily-budget calculator total-budget pacing simulator nahi.','Write the allowed total spend and duration for each plan. The app’s daily-budget calculator does not simulate total-budget pacing.']},
{file:'rsa-url-paths.jpg',date:'22 Oct 2026',width:280,practice:'studio',sources:['rsa'],title:['RSA ka URL aur display paths','RSA URL and display paths'],path:'Keywords and ads → Ads → Final URL / Display path',pins:[[48,25],[30,82]],notes:[['Final URL actual destination hai. Working, relevant page aur redirect path verify karo; yahan field blank hai.','Final URL is the actual destination. Verify the working, relevant page and redirects; the field is blank here.'],['Display paths ke 15-character counters hain. Ye visible URL text hain; destination URL ko change nahi kartay.','Display paths have 15-character counters. They are visible URL text and do not change the destination.']],task:['Studio mein relevant final URL aur do readable paths ka fictional draft banao. Phir landing-page lab mein message match review karo.','Draft a relevant final URL and two readable paths in the studio. Review message match in the landing-page lab.']},
{file:'rsa-headlines.jpg',date:'22 Oct 2026',width:280,practice:'studio',sources:['rsa'],title:['RSA headlines aur required fields','RSA headlines and required fields'],path:'Keywords and ads → Ads → Headlines',pins:[[35,11],[80,45],[80,97]],notes:[['0/15 headline asset count hai. Puri capacity fill karna relevance ki guarantee nahi; useful distinct messages likho.','0/15 is the headline-asset count. Filling every slot does not guarantee relevance; write useful distinct messages.'],['Har headline ka counter 30 characters tak hai. Required labels minimum fields ko identify karte hain. Actual editor ki validation separately check karo.','Each headline has a 30-character counter. Required labels identify minimum fields. Check the actual editor’s validation separately.'],['Kam az kam 3 headlines chahiye. Is capture mein fields khaali hain; koi live creative save ya approve nahi hua.','At least three headlines are needed. Fields are empty here; no live creative was saved or approved.']],task:['RSA studio mein 3 useful headlines likho, phir 15 tak sirf meaningful alternatives add karo.','Write three useful headlines in the studio, adding meaningful alternatives up to 15.']},
{file:'rsa-pinning.jpg',date:'22 Oct 2026',width:414,practice:'studio',sources:['rsa'],title:['Asli pin-position menu','The original pin-position menu'],path:'RSA → Headline → Pin options',pins:[[30,18],[30,38],[30,80]],notes:[['Unpinned headline available slots mein rotate ho sakti hai. Menu ki illustration actual serving ka guarantee nahi.','An unpinned headline can rotate into available slots. The menu illustration does not guarantee serving.'],['Position 1 ya 2 ke liye pin combinations restrict karta hai. Sirf zaroori messaging ki clear reason par pin lagao.','Pinning to position one or two restricts combinations. Pin essential messaging for a clear reason.'],['Position 3 har format mein guaranteed nahi. Essential message ko sirf H3 par depend mat karao.','Position three is not guaranteed in every format. Do not rely only on H3 for essential messaging.']],task:['Studio mein do headlines same position par pin karo aur sample alternatives dekho.','Pin two headlines to the same position in the studio and inspect sample alternatives.']},
{file:'rsa-descriptions.jpg',date:'22 Oct 2026',width:280,practice:'studio',sources:['rsa'],title:['Descriptions ka asli editor','The original description editor'],path:'Keywords and ads → Ads → Descriptions',pins:[[35,11],[80,42],[25,90]],notes:[['0/4 description-asset count hai; kam az kam 2 descriptions chahiye. Headline aur description separate assets hain.','0/4 is the description-asset count; at least two descriptions are needed. Headlines and descriptions are separate assets.'],['Har description ka limit 90 characters hai. Claims aur destination par available offer ko bhi review karo.','Each description allows 90 characters. Also review claims and whether the offer exists at the destination.'],['Add Description se extra alternatives aati hain. Blank editor ka Incomplete status approval ya predicted results ki report nahi.','Add Description adds alternatives. A blank editor’s Incomplete status is not an approval or results report.']],task:['Studio mein 2–4 descriptions likho: service/benefit, relevant conditions aur clear next action.','Write two to four studio descriptions covering the service/benefit, relevant conditions and a clear next action.']}

];
let screenIndex=0,screenPin=0;
function screensPage(){if(location.hash.startsWith('#screens/')){screenIndex=Math.max(0,Math.min(REAL_SCREENS.length-1,route().id));screenPin=Math.min(screenPin,REAL_SCREENS[screenIndex].pins.length-1);}const s=REAL_SCREENS[screenIndex];return `${heading('REAL GOOGLE ADS · CAPTURED 20 & 22 OCT 2026',U('Screen dekho. Step samjho.','See the screen. Understand the step.'),U(REAL_SCREENS.length+' original interface crops. Number dabao aur asaan explanation parho.',REAL_SCREENS.length+' original interface crops. Tap a number for a simple explanation.'))}<div class="note">${U('Ye real UI captures hain, live controls nahi. Account details crop ki gayi hain; pixels recreate nahi kiye. Layout aur available features account ke mutabiq badal saktay hain.','These are real UI captures, not live controls. Account details are cropped out; pixels have not been recreated. Layout and features may vary by account.')}</div><div class="action-row" style="margin:22px 0"><label class="field" style="flex:1;min-width:230px;margin:0">${U('Original screen choose karo','Choose an original screen')}<select id="screen-select" aria-label="Choose original screen">${REAL_SCREENS.map((x,i)=>`<option value="${i}" ${i===screenIndex?'selected':''}>${i+1}/${REAL_SCREENS.length} · ${esc(t(x.title))}</option>`).join('')}</select></label><button class="btn light" data-screen="${Math.max(0,screenIndex-1)}" ${screenIndex===0?'disabled':''}>← ${U('Pichli','Previous')}</button><button class="btn light" data-screen="${Math.min(REAL_SCREENS.length-1,screenIndex+1)}" ${screenIndex===REAL_SCREENS.length-1?'disabled':''}>${U('Agli','Next')} →</button></div><div class="screenshot-layout"><article class="card"><div class="eyebrow">${esc(s.path)}</div><h2>${esc(t(s.title))}</h2><figure class="real-screen"><img src="assets/google-ads/${s.file}" alt="${esc(t(s.title))} — original Google Ads interface crop" width="${s.width||(screenIndex===3?335:screenIndex===0?487:screenIndex===4?470:558)}">${s.pins.map(([x,y],i)=>`<button class="screen-pin ${screenPin===i?'active':''}" style="left:${x}%;top:${y}%" data-pin="${i}" aria-label="${U('Point','Point')} ${i+1}" aria-pressed="${screenPin===i}">${i+1}</button>`).join('')}</figure><p class="screen-credit">© Google · Original UI crop · Captured ${s.date||'20 Oct 2026'} · <a href="assets/google-ads/${s.file}" target="_blank" rel="noopener">${U('Original kholo / zoom','Open original / zoom')}</a></p></article><aside class="card"><div class="eyebrow">POINT ${screenPin+1}</div><p id="screen-explanation" class="guide-instruction" aria-live="polite">${esc(t(s.notes[screenPin]))}</p><div class="example"><div class="label">${U('AB KHUD SOCHO','YOUR TURN')}</div><p>${esc(t(s.task))}</p></div><div class="action-row"><button class="btn light" data-go="guides">${U('Setup workbook','Setup workbook')} →</button><button class="btn light" data-go="${s.practice||'workshop'}">${U('Related practice kholo','Open related practice')} →</button></div></aside></div><section class="card" style="margin-top:20px"><h3>${U('Agli screenshots mein kya baqi hai?','Which screenshots are still missing?')}</h3><p>${U('Planner entry/inputs aur Diagnostics entry ab available hain. Bidding, budget aur RSA ke control captures ab available hain. Negatives, search terms, Planner results aur conversion-action diagnostics ke complete workflows abhi baqi hain. Workbooks aur simulations in gaps ko original screenshots keh kar present nahi kartay.','Planner entry/inputs and the Diagnostics entry are available. Bidding, budget and RSA control captures are available. Complete workflows for negatives, search terms, Planner results and action-specific diagnostics remain. Workbooks and simulations are not presented as original screenshots.')}</p>${sourceLinks(s.sources||['settings','tracking'])}</section>${footer()}`;}
function bindScreens(){$('#screen-select').onchange=e=>{screenPin=0;go('screens/'+e.target.value);};$$('[data-screen]').forEach(b=>b.onclick=()=>{screenIndex=+b.dataset.screen;screenPin=0;if(location.hash==='#screens/'+screenIndex)render();else go('screens/'+screenIndex);});$$('[data-pin]').forEach(b=>b.onclick=()=>{screenPin=+b.dataset.pin;const y=window.scrollY;render();window.scrollTo(0,y);});}
